const routeAliases:Record<string,[string,string]>={
  "/school":["Dashboard","Dashboard"],"/school/dashboard":["Dashboard","Dashboard"],
  "/school/search-due-fees":["Finance & Fees","Search Due Fees"],"/school/fee-transactions":["Finance & Fees","All Transactions"],
  "/school/online-transactions":["Finance & Fees","Online Transactions"],"/school/generate-due-slip":["Finance & Fees","Generate Due Slip"],
  "/school/due-slip-history":["Finance & Fees","Due Slip History"],"/school/accounts-dashboard":["Accounts","Accounts Dashboard"],
  "/school/income":["Accounts","Income"],"/school/expense":["Accounts","Expense"],"/school/income-heads":["Accounts","Income Heads"],
  "/school/expense-heads":["Accounts","Expense Heads"],"/school/my-settings":["Settings & Billing","School Settings"],
  "/school/support":["Help Center","Browse Articles"],"/school/notifications":["Communicate","Notice Board"],
  "/school/classes/create":["Academics","Classes"],"/school/subjects/create":["Academics","Subjects"],
  "/school/academic-sessions/create":["Academics","Academic Sessions"],"/school/exams/create":["Offline Examinations","Manage Offline Exams"],
};
function routeSelection(pathname:string):[string,string]{
  if(routeAliases[pathname])return routeAliases[pathname];
  for(const [group,routes] of moduleRouteMaps){const match=Object.entries(routes).find(([,path])=>path===pathname);if(match)return[group,match[0]];}
  return["Dashboard","Dashboard"];
}

