const libraryTabs:[string,string][]=[["Overview","Library Dashboard"],["Guide","Library Guide"],["Issue/Return Book","Issue/Return Book"],["Categories","Book Categories"],["Manage Books","Manage Books"],["Book Requests","Book Requests"]];

function LibraryReferencePage({page,foundation,students,onPage,onCreate,onSaved}:{page:string;foundation:Foundation;students:Student[];onPage:(p:string)=>void;onCreate:(p:Record<string,unknown>)=>Promise<boolean>;onSaved:(message:string)=>void}){
  const [books,setBooks]=useState(initialLibraryBooks),[issues,setIssues]=useState(initialLibraryIssues),[categories,setCategories]=useState(["Academic","Biography","Children","Fiction","Reference"]),[requests,setRequests]=useState(initialLibraryRequests),[selectedBookId,setSelectedBookId]=useState("lb1");
  const selectedBook=books.find(x=>x.id===selectedBookId)??books[0];
  const persist=(workflow:string,title:string,description:string)=>void onCreate({action:"create_record",moduleKey:"Library",workflow,title,description,recordDate:new Date().toISOString().slice(0,10),dueDate:null,amountPaise:null,assignee:"Librarian",priority:"normal"});
  const saveBook=(book:LibraryBook)=>{setBooks(v=>v.some(x=>x.id===book.id)?v.map(x=>x.id===book.id?book:x):[book,...v]);setSelectedBookId(book.id);persist("Manage Books",book.title,`${book.author} · ISBN ${book.isbn} · ${book.quantity} copies`);onSaved(book.id.startsWith("new-")?"Book added to the library catalogue.":"Book details updated.");onPage("Manage Books");};
  if(page==="Add Book")return <LibraryBookForm title="Add New Book" book={null} categories={categories} foundation={foundation} onBack={()=>onPage("Manage Books")} onSave={saveBook}/>;
  if(page==="Edit Book")return <LibraryBookForm title="Edit Book" book={selectedBook} categories={categories} foundation={foundation} onBack={()=>onPage("Book Details")} onSave={saveBook}/>;
  if(page==="Bulk Upload")return <LibraryBulkUpload onBack={()=>onPage("Manage Books")} onSaved={()=>{onSaved("Library import processed successfully.");onPage("Manage Books");}}/>;
  if(page==="Print Barcodes")return <LibraryBarcodes books={books} onBack={()=>onPage("Manage Books")}/>;
  if(page==="Book Details")return <LibraryBookDetails book={selectedBook} issues={issues.filter(x=>x.bookId===selectedBook.id)} onBack={()=>onPage("Manage Books")} onEdit={()=>onPage("Edit Book")}/>;
  return <><LibraryHeader page={page} requests={requests} onPage={onPage}/>{page==="Library Guide"?<LibraryGuide/>:page==="Issue/Return Book"?<LibraryCirculation books={books} setBooks={setBooks} issues={issues} setIssues={setIssues} students={students} onSaved={onSaved}/>:page==="Manage Books"?<LibraryBooks books={books} onPage={onPage} onSelect={id=>{setSelectedBookId(id);onPage("Book Details");}} onEdit={id=>{setSelectedBookId(id);onPage("Edit Book");}}/>:page==="Book Categories"?<LibraryCategories categories={categories} books={books} setCategories={setCategories}/>:page==="Book Requests"?<LibraryRequests requests={requests} books={books} onChange={(id,status)=>{setRequests(v=>v.map(x=>x.id===id?{...x,status}:x));onSaved(`Book request marked ${status.toLowerCase()}.`);}} onIssue={request=>{setRequests(v=>v.map(x=>x.id===request.id?{...x,status:"Approved"}:x));onPage("Issue/Return Book");}}/>:<LibraryDashboard books={books} issues={issues} onPage={onPage} onSelect={id=>{setSelectedBookId(id);onPage("Book Details");}} onSaved={onSaved}/>}</>;
}
function LibraryHeader({page,requests,onPage}:{page:string;requests:LibraryRequest[];onPage:(p:string)=>void}){const pending=requests.filter(x=>x.status==="Pending").length;return <><div className={styles.libraryHeader}><div><span>LB</span><div><h1>Library Management</h1><p>Real-time monitoring of campus-wide literary resources and circulation metrics.</p></div></div><div><button onClick={()=>globalThis.print()}>Export Inventory</button><button onClick={()=>onPage("Add Book")}>＋ New Acquisition</button></div></div><nav className={styles.libraryTabs}>{libraryTabs.map(([label,target])=><button className={page===target?styles.libraryTabActive:""} onClick={()=>onPage(target)} key={target}>{label}{label==="Book Requests"&&pending>0?<b>{pending}</b>:null}</button>)}</nav></>}

function LibraryDashboard({books,issues,onPage,onSelect,onSaved}:{books:LibraryBook[];issues:LibraryIssue[];onPage:(p:string)=>void;onSelect:(id:string)=>void;onSaved:(message:string)=>void}){const total=books.reduce((n,x)=>n+x.quantity,0),issued=issues.filter(x=>x.status==="Issued"||x.status==="Overdue").length,overdue=issues.filter(x=>x.status==="Overdue");return <><section className={styles.libraryStats}>{[["BK","Total Books",total,"12%"],["IS","Issued Books",issued,"Active"],["OD","Overdue Returns",overdue.length,"Critical"],["NA","New Acquisitions",0,"This month"]].map(([icon,label,value,note])=><article key={String(label)}><i>{icon}</i><span><small>{label}</small><b>{value}</b></span><em>{note}</em></article>)}</section><section className={styles.libraryDashboardGrid}><article className={`${styles.panel} ${styles.libraryCatalog}`}><PanelHead title="Library Catalog" subtitle={`Showing recent ${Math.min(books.length,10)} of ${books.length} titles`} action="View All" onClick={()=>onPage("Manage Books")}/><LibraryBookTable books={books} onSelect={onSelect}/></article><aside className={`${styles.panel} ${styles.overduePanel}`}><PanelHead title="Overdue Alerts" subtitle={`${overdue.length} need attention`}/>{overdue.length?overdue.map(x=><div key={x.id}><i>!</i><p><b>{x.member}</b><span>“{x.bookTitle}”</span><strong>{Math.ceil(x.fine/5)} DAYS LATE</strong></p><button onClick={()=>onSaved(`Reminder sent to ${x.member}.`)}>Notify Student</button></div>):<Empty icon="✓" title="No overdue books" text="All issued books are within their due dates."/>}</aside><article className={styles.panel}><PanelHead title="Circulation Trends" subtitle="Issues and returns — last 8 weeks"/><div className={styles.libraryTrend}>{[35,58,44,72,63,81,67,88].map((x,i)=><i key={i} style={{height:`${x}%`}}><span>{i+1}</span></i>)}</div></article><article className={styles.panel}><PanelHead title="Recent Returns" subtitle="Latest circulation activity"/><div className={styles.libraryReturns}>{issues.filter(x=>x.status==="Returned").map(x=><div key={x.id}><i>{initials(x.member)}</i><p><b>{x.member}</b><span>{x.bookTitle}</span></p><time>{x.returned}</time></div>)}</div></article></section></>}
function LibraryBookTable({books,onSelect}:{books:LibraryBook[];onSelect:(id:string)=>void}){return <div className={styles.libraryBookTable}><div>{["Book Title","Author","Category","Status","Actions"].map(x=><b key={x}>{x}</b>)}</div>{books.map(x=><div key={x.id}><span className={`${styles.bookMiniCover} ${styles[`book${x.tone}`]}`}>BK</span><p><b>{x.title}</b><small>ISBN: {x.isbn||"N/A"}</small></p><span>{x.author}<small>{x.publisher}</small></span><em>{x.category}</em><strong>{x.available>0?`Available (${x.available})`:"Out of stock"}</strong><button onClick={()=>onSelect(x.id)}>View</button></div>)}</div>}

function LibraryCirculation({books,setBooks,issues,setIssues,students,onSaved}:{books:LibraryBook[];setBooks:(updater:(v:LibraryBook[])=>LibraryBook[])=>void;issues:LibraryIssue[];setIssues:(updater:(v:LibraryIssue[])=>LibraryIssue[])=>void;students:Student[];onSaved:(message:string)=>void}){const members=[...students.map(x=>({id:x.id,name:x.fullName,type:"Student"})),{id:"staff-1",name:"Amit Sharma",type:"Staff"},{id:"staff-2",name:"Sneha Desai",type:"Staff"}],[rapid,setRapid]=useState(false),[returnMember,setReturnMember]=useState("");const activeForMember=issues.filter(x=>x.member===returnMember&&(x.status==="Issued"||x.status==="Overdue"));function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();const f=new FormData(e.currentTarget),member=members.find(x=>x.id===f.get("member")),book=books.find(x=>x.id===f.get("book"));if(!member||!book)return;setIssues(v=>[{id:crypto.randomUUID(),bookId:book.id,bookTitle:book.title,member:member.name,memberType:member.type,issued:String(f.get("issued")),due:String(f.get("due")),returned:"",fine:0,status:"Issued"},...v]);setBooks(v=>v.map(x=>x.id===book.id?{...x,available:Math.max(0,x.available-1)}:x));onSaved(`${book.title} issued to ${member.name}.`);e.currentTarget.reset();}function returnBook(issue:LibraryIssue){setIssues(v=>v.map(x=>x.id===issue.id?{...x,status:"Returned",returned:new Date().toISOString().slice(0,10)}:x));setBooks(v=>v.map(x=>x.id===issue.bookId?{...x,available:Math.min(x.quantity,x.available+1)}:x));onSaved(`${issue.bookTitle} returned. Fine: ₹${issue.fine}.`);}return <><div className={styles.circulationMode}><button className={!rapid?styles.circulationActive:""} onClick={()=>setRapid(false)}>Issue / Return Desk</button><button className={rapid?styles.circulationActive:""} onClick={()=>setRapid(true)}>▣ Rapid Scan</button></div>{rapid?<section className={styles.rapidScan}><div><i>▤</i><h2>Rapid Scan Desk</h2><p>Scan a member ID first, then scan book barcodes to issue or return without using a mouse.</p><label>Member ID / Barcode<input autoFocus placeholder="Scan student or staff card…"/></label><label>Book Barcode<input placeholder="Scan a book after the member…"/></label><span>Waiting for member scan</span></div><aside><h3>Scanner Sequence</h3><p><b>1</b> Scan member ID</p><p><b>2</b> Review current issues</p><p><b>3</b> Scan book to issue or return</p><small>Book scans are rejected until a member is selected.</small></aside></section>:<><section className={styles.circulationGrid}><article className={styles.panel}><PanelHead title="Issue a Book" subtitle="Choose a student or staff member and an available title"/><form onSubmit={submit}><label>Select Member (Student/Staff) *<select name="member" required><option value="">Search by Name or Admission No...</option>{members.map(x=><option value={x.id} key={x.id}>{x.name} · {x.type}</option>)}</select></label><label>Search Book *<select name="book" required><option value="">Search for an available book...</option>{books.filter(x=>x.available>0).map(x=><option value={x.id} key={x.id}>{x.title} · {x.available} available</option>)}</select></label><label>Issue Date *<input name="issued" type="date" required defaultValue={new Date().toISOString().slice(0,10)}/></label><label>Due Date *<input name="due" type="date" required/></label><button>Issue Book</button></form></article><article className={styles.panel}><PanelHead title="Return a Book" subtitle="Select a member to view books currently issued"/><div className={styles.returnDesk}><label>Select Member<select value={returnMember} onChange={e=>setReturnMember(e.target.value)}><option value="">Search for a member to return a book...</option>{members.map(x=><option value={x.name} key={x.id}>{x.name}</option>)}</select></label>{returnMember?(activeForMember.length?activeForMember.map(x=><div key={x.id}><span><b>{x.bookTitle}</b><small>Due {x.due} · {x.status}</small></span><button onClick={()=>returnBook(x)}>Return Book</button></div>):<Empty icon="✓" title="No active issues" text="This member has no books to return."/>):<Empty icon="RT" title="Select Member to View Issued Books" text="Select a member to see the books they have issued."/>}</div></article></section><article className={styles.panel}><PanelHead title="Recently Issued Books" subtitle={`${issues.length} recent circulation records`}/><SimpleRecordTable headers={["Book Title","Member Name","Issue Date","Due Date","Status"]} rows={issues.map(x=>[x.bookTitle,x.member,x.issued,x.due,x.status])}/></article></>}</>}

function LibraryBooks({books,onPage,onSelect,onEdit}:{books:LibraryBook[];onPage:(p:string)=>void;onSelect:(id:string)=>void;onEdit:(id:string)=>void}){const [search,setSearch]=useState("");const filtered=books.filter(x=>`${x.title} ${x.author} ${x.isbn} ${x.category}`.toLowerCase().includes(search.toLowerCase()));return <><div className={styles.libraryActionBar}><div><button onClick={()=>onPage("Print Barcodes")}>▥ Download Barcodes</button><button onClick={()=>onPage("Bulk Upload")}>⇧ Bulk Upload</button><button onClick={()=>onPage("Add Book")}>＋ Add New Book</button></div><label>⌕<input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search books…"/></label></div><article className={styles.panel}><PanelHead title="All Library Books" subtitle={`${filtered.length} catalogue records`}/><CommExport/><div className={styles.manageBooksTable}><div>{["#","Cover","Title","Author","Category","Qty","Available","Actions"].map(x=><b key={x}>{x}</b>)}</div>{filtered.map((x,i)=><div key={x.id}><span>{i+1}</span><i className={`${styles.bookMiniCover} ${styles[`book${x.tone}`]}`}>BK</i><p><b>{x.title}</b><small>ISBN: {x.isbn}</small></p><span>{x.author}<small>{x.publisher}</small></span><em>{x.category}</em><span>{x.quantity}</span><strong>{x.available}</strong><span><button onClick={()=>onSelect(x.id)}>View</button><button onClick={()=>onEdit(x.id)}>Edit</button><button>⋮</button></span></div>)}</div><TablePager count={filtered.length}/></article></>}
function LibraryCategories({categories,books,setCategories}:{categories:string[];books:LibraryBook[];setCategories:(updater:(v:string[])=>string[])=>void}){const [search,setSearch]=useState(""),[modal,setModal]=useState(false),[name,setName]=useState("");const filtered=categories.filter(x=>x.toLowerCase().includes(search.toLowerCase()));return <><div className={styles.libraryActionBar}><button onClick={()=>setModal(true)}>＋ Add New Category</button><label>⌕<input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search categories…"/></label></div><article className={styles.panel}><PanelHead title="All Book Categories" subtitle={`${filtered.length} categories`}/><CommExport/><div className={styles.categoryTable}><div>{["#","Category Name","Books","Actions"].map(x=><b key={x}>{x}</b>)}</div>{filtered.map((x,i)=><div key={x}><span>{i+1}</span><p><i>CT</i><b>{x}</b></p><span><strong>{books.filter(b=>b.category===x).length}</strong> books</span><span><button>Edit</button><button>Delete</button></span></div>)}</div><TablePager count={filtered.length}/></article>{modal&&<div className={styles.commModal}><form onSubmit={e=>{e.preventDefault();if(name.trim())setCategories(v=>v.includes(name.trim())?v:[...v,name.trim()]);setModal(false);setName("");}}><header><h2>Add New Category</h2><button type="button" onClick={()=>setModal(false)}>×</button></header><label>Category Name *<input value={name} onChange={e=>setName(e.target.value)} required placeholder="e.g., Science Fiction"/></label><div className={styles.modalActions}><button type="button" onClick={()=>setModal(false)}>Close</button><button>Save Category</button></div></form></div>}</>}

function LibraryRequests({requests,books,onChange,onIssue}:{requests:LibraryRequest[];books:LibraryBook[];onChange:(id:string,status:string)=>void;onIssue:(request:LibraryRequest)=>void}){const [filter,setFilter]=useState("Pending");const filters=["Pending","Approved","Fulfilled","Rejected","All"],shown=requests.filter(x=>filter==="All"||x.status===filter);return <><div className={styles.requestFilters}>{filters.map(x=><button className={filter===x?styles.requestFilterActive:""} onClick={()=>setFilter(x)} key={x}>{x} {x!=="All"&&<b>{requests.filter(r=>r.status===x).length}</b>}</button>)}</div><article className={styles.panel}><PanelHead title="Book Requests" subtitle={`${shown.length} ${filter.toLowerCase()} requests`}/><div className={styles.requestTable}><div>{["Requested By","Book","Requested On","Status","Actions"].map(x=><b key={x}>{x}</b>)}</div>{shown.map(x=>{const book=books.find(b=>b.id===x.bookId);return <div key={x.id}><p><i>{initials(x.member)}</i><span><b>{x.member}</b><small>Student · {x.memberNo}</small></span></p><p><b>{x.bookTitle}</b><small>{x.author} · {book?.available??0} in stock</small></p><span>{x.requested}</span><em className={styles[`request${x.status.toLowerCase()}`]}>{x.status}</em><span>{x.status==="Pending"&&<><button onClick={()=>onIssue(x)}>Approve</button><button onClick={()=>onChange(x.id,"Rejected")}>Reject</button></>}{x.status==="Approved"&&<button onClick={()=>onChange(x.id,"Fulfilled")}>Mark Fulfilled</button>}</span></div>})}</div></article></>}

function LibraryGuide(){const phases=[["01","Build the catalogue","Create categories, fetch by ISBN, add books, bulk import and print barcodes."],["02","Issue & return","Choose a student or staff member, select an available copy and set the due date."],["03","Overdue & fines","Monitor late books, notify families and calculate days late × the daily fine."],["04","Book requests","Approve, fulfil or reject reservations submitted through the parent and student apps."]];return <><section className={styles.libraryGuideHero}><span>LIBRARY MODULE GUIDE</span><h2>How the Library module works</h2><p>Build a structured catalogue, circulate physical and digital books, manage returns and fines, and fulfil reservations from one connected workspace.</p></section><section className={styles.libraryFlow}>{["Categories","Catalogue","Circulate","Overdue & Fines"].map((x,i)=><div key={x}><i>{i+1}</i><b>{x}</b><small>{["Shelf structure","Books & copies","Issue & return","Late returns"][i]}</small></div>)}</section><section className={styles.libraryGuideGrid}>{phases.map(([n,title,text])=><article className={styles.panel} key={n}><span>{n}</span><h3>{title}</h3><p>{text}</p><ul><li>Session-aware records and access</li><li>Automatic copy availability</li><li>Audit-ready circulation history</li></ul></article>)}</section><article className={`${styles.panel} ${styles.libraryRules}`}><PanelHead title="Important operating rules" subtitle="Controls that protect catalogue accuracy"/><div>{["A book with zero available copies cannot be issued.","A member cannot hold two active issues of the same title.","Due date must be on or after the issue date.","Return restores availability and records any fine.","Rapid Scan always requires the member ID first.","E-books are excluded from physical barcode printing."].map((x,i)=><p key={x}><i>{i+1}</i>{x}</p>)}</div></article></>}

function LibraryBookForm({title,book,categories,foundation,onBack,onSave}:{title:string;book:LibraryBook|null;categories:string[];foundation:Foundation;onBack:()=>void;onSave:(book:LibraryBook)=>void}){const [fetch,setFetch]=useState(""),[bookType,setBookType]=useState(book?.bookType??"Physical Only");return <section className={styles.libraryFormPage}><div className={styles.libraryFormHeading}><div><button onClick={onBack}>← Back</button><h1>{title}</h1><p>{book?.title??"Search by ISBN to fill details automatically, or enter them by hand"}</p></div>{book&&<button onClick={onBack}>View Book</button>}</div><section className={styles.libraryBookFormLayout}><form className={`${styles.panel} ${styles.libraryBookForm}`} onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);onSave({id:book?.id??`new-${crypto.randomUUID()}`,title:String(f.get("title")),author:String(f.get("author")),publisher:String(f.get("publisher")),isbn:String(f.get("isbn")),category:String(f.get("category")),className:String(f.get("className")),year:String(f.get("year")),edition:String(f.get("edition")),language:String(f.get("language")),pages:Number(f.get("pages")),subject:String(f.get("subject")),rack:String(f.get("rack")),quantity:Number(f.get("quantity")),available:book?Math.max(0,book.available+Number(f.get("quantity"))-book.quantity):Number(f.get("quantity")),description:String(f.get("description")),bookType,ebookUrl:String(f.get("ebookUrl")),tone:book?.tone??"blue"});}}><h2 className={styles.formWide}>Book Details</h2><div className={`${styles.formWide} ${styles.isbnFetch}`}><label>Auto-Fill from Google Books<input value={fetch} onChange={e=>setFetch(e.target.value)} placeholder="Enter ISBN number or Book Title to auto-fill..."/></label><button type="button" onClick={()=>setFetch("9780141036144")}>Fetch</button><small>Type an ISBN or title, then click Fetch to populate the catalogue fields.</small></div><label className={styles.formWide}>Book Title *<input name="title" required defaultValue={book?.title}/></label><label>Category<select name="category" defaultValue={book?.category}><option value="">-- All Categories --</option>{categories.map(x=><option key={x}>{x}</option>)}</select></label><label>Class Restriction (optional)<select name="className" defaultValue={book?.className}><option>All Classes</option>{foundation.classes.map(x=><option key={x.id}>{x.name}</option>)}</select></label><label>Author<input name="author" defaultValue={book?.author}/></label><label>Publisher<input name="publisher" defaultValue={book?.publisher}/></label><label>ISBN Number<input name="isbn" defaultValue={book?.isbn}/></label><label>Publication Year<input name="year" type="number" defaultValue={book?.year}/></label><label>Edition<input name="edition" defaultValue={book?.edition}/></label><label>Language<input name="language" defaultValue={book?.language??"English"}/></label><label>Page Count<input name="pages" type="number" defaultValue={book?.pages}/></label><label>Subject / Genre<input name="subject" defaultValue={book?.subject}/></label><label>Rack Number<input name="rack" defaultValue={book?.rack}/></label><label>Quantity *<input name="quantity" type="number" min="1" required defaultValue={book?.quantity??1}/><small>{book?`${book.available} of ${book.quantity} currently on the shelf.`:"Initial total and available copies."}</small></label><label className={styles.formWide}>Description<textarea name="description" defaultValue={book?.description} placeholder="Book description or synopsis..."/></label><label className={styles.formWide}>Upload Cover Image<input type="file" accept="image/*"/><small>Leave blank to keep the current or Google Books cover.</small></label><h2 className={styles.formWide}>E-Library / Digital Book</h2><label>Book Type<select value={bookType} onChange={e=>setBookType(e.target.value)}><option>Physical Only</option><option>E-Book Only</option><option>Physical + E-Book</option></select></label><label>E-Book URL<input name="ebookUrl" type="url" defaultValue={book?.ebookUrl} disabled={bookType==="Physical Only"} placeholder="https://drive.google.com/file/d/..."/></label><FormActions cancel={onBack} submit={book?"Update Book":"Add Book"}/></form><aside className={`${styles.panel} ${styles.bookFormHelp}`}><div className={`${styles.bookLargeCover} ${styles[`book${book?.tone??"blue"}`]}`}>BOOK</div><h3>{book?.title??"Cover Preview"}</h3><p>Catalogue records support bibliographic data, physical copy tracking, shelf location, class restriction and digital access.</p><ul><li>Use ISBN fetch to reduce typing</li><li>Quantity controls copy availability</li><li>Rack numbers improve findability</li><li>Digital-only books need no barcode</li></ul></aside></section></section>}

function LibraryBookDetails({book,issues,onBack,onEdit}:{book:LibraryBook;issues:LibraryIssue[];onBack:()=>void;onEdit:()=>void}){const issued=issues.filter(x=>x.status!=="Returned"),availability=Math.round(book.available/Math.max(1,book.quantity)*100);return <><div className={styles.bookDetailHeader}><div><h1>Book Details</h1><p>{book.title}</p></div><button onClick={onBack}>← Back</button><button onClick={onEdit}>Edit</button></div><section className={styles.bookDetailGrid}><article className={`${styles.panel} ${styles.bookIdentity}`}><div className={`${styles.bookLargeCover} ${styles[`book${book.tone}`]}`}>BOOK</div><div><h2>{book.title}</h2><p>{book.author}</p><em>{book.available} of {book.quantity} available</em><dl><div><dt>ISBN</dt><dd>{book.isbn}</dd></div><div><dt>Category</dt><dd>{book.category}</dd></div><div><dt>Publisher</dt><dd>{book.publisher}</dd></div><div><dt>Rack</dt><dd>{book.rack}</dd></div><div><dt>Language</dt><dd>{book.language}</dd></div><div><dt>Type</dt><dd>{book.bookType}</dd></div></dl></div></article><aside className={`${styles.panel} ${styles.bookStats}`}><PanelHead title="Statistics" subtitle="Live circulation status"/><div>{[["Total Copies",book.quantity],["Available",book.available],["Currently Issued",issued.length],["Times Issued (All Time)",issues.length]].map(([x,v])=><p key={String(x)}><span>{x}</span><b>{v}</b></p>)}</div><footer><strong>{availability}% availability</strong><i><b style={{width:`${availability}%`}}/></i></footer></aside></section><section className={styles.twoCols}><article className={styles.panel}><PanelHead title="Currently Issued To" subtitle={`${issued.length} out`}/><SimpleRecordTable headers={["Member","Type","Issue Date","Due Date","Status"]} rows={issued.map(x=>[x.member,x.memberType,x.issued,x.due,x.status])}/></article><article className={styles.panel}><PanelHead title="Issue History" subtitle={`${issues.length} total`}/><SimpleRecordTable headers={["Member","Issued","Due","Returned","Fine","Status"]} rows={issues.map(x=>[x.member,x.issued,x.due,x.returned||"—",x.fine?`₹${x.fine}`:"—",x.status])}/></article></section></>}
function LibraryBulkUpload({onBack,onSaved}:{onBack:()=>void;onSaved:()=>void}){return <section className={styles.libraryFormPage}><div className={styles.libraryFormHeading}><div><h1>Bulk Book Upload</h1><p>Import many books at once from a CSV or Excel file</p></div></div><section className={styles.libraryUploadGrid}><form className={`${styles.panel} ${styles.bulkUploadCard}`} onSubmit={e=>{e.preventDefault();onSaved();}}><PanelHead title="Upload Library Book Data" subtitle="Supported formats: .csv, .xls, .xlsx"/><label>Upload CSV or Excel File *<input type="file" accept=".csv,.xls,.xlsx" required/></label><footer><button type="button" onClick={onBack}>Back to List</button><button>Process Upload</button></footer></form><aside className={`${styles.panel} ${styles.bulkInstructions}`}><PanelHead title="Instructions & Template" subtitle="Use the expected column names"/><button>⇩ CSV Template</button><p>Required fields are marked with an asterisk.</p><ul><li><b>Required:</b> title, category_name, quantity.</li><li>Category name must exactly match an existing category.</li><li>Class name is optional and must match an existing class.</li><li>Quantity must be a positive integer.</li><li>Book type: physical, ebook or both.</li><li>Author, publisher, ISBN, rack, language, edition, cover and e-book URL are supported.</li></ul></aside></section></section>}
function LibraryBarcodes({books,onBack}:{books:LibraryBook[];onBack:()=>void}){const physical=books.filter(x=>x.bookType!=="E-Book Only");return <section className={styles.barcodePage}><div><button onClick={onBack}>← Back to Books</button><h1>Print Library Barcodes</h1><button onClick={()=>globalThis.print()}>Print Barcodes</button></div><section className={styles.barcodeSheet}>{physical.flatMap(book=>Array.from({length:Math.min(book.quantity,4)},(_,i)=><article key={`${book.id}-${i}`}><b>{book.title}</b><span>{book.author}</span><div>║▌║║▌▌║▌║║▌║</div><small>{book.isbn}-{String(i+1).padStart(3,"0")}</small></article>))}</section></section>}

