function HelpCenterReferencePage({page,onPage}:{page:string;onPage:(p:string)=>void}){
  const [categories,setCategories]=useState(initialKbCategories),[articles,setArticles]=useState(initialKbArticles),[selectedId,setSelectedId]=useState("ka1"),[toast,setToast]=useState("");
  const notify=(text:string)=>{setToast(text);globalThis.setTimeout(()=>setToast(""),2800);};
  let content:ReactNode;
  if(page==="Add KB Category")return <KbCategoryForm categories={categories} onBack={()=>onPage("Manage Categories")} onSave={category=>{setCategories(v=>[...v,category]);notify("Knowledge-base category created.");onPage("Manage Categories");}}/>;
  if(page==="Add Article")return <KbArticleForm categories={categories} onBack={()=>onPage("Browse Articles")} onSave={article=>{setArticles(v=>[article,...v]);notify("Article saved successfully.");onPage("Browse Articles");}}/>;
  if(page==="Article Details"){const article=articles.find(x=>x.id===selectedId)??articles[0];return <KbArticleDetails article={article} onBack={()=>onPage("Browse Articles")}/>;}
  if(page==="Browse Articles")content=<KbArticles articles={articles} categories={categories} onPage={onPage} onOpen={id=>{setSelectedId(id);onPage("Article Details");}}/>;
  else if(page==="AI Chatbot")content=<KbChatbot articles={articles}/>;
  else content=<KbCategories categories={categories} articles={articles} onPage={onPage} onToggle={id=>setCategories(v=>v.map(x=>x.id===id?{...x,active:!x.active}:x))}/>;
  return <><section className={styles.kbHeader}><div><span>HIG KNOWLEDGE BASE</span><h1>{page==="AI Chatbot"?"AI Assistant":page==="Browse Articles"?"Help Center":"KB Categories"}</h1><p>Guides, FAQs and school-aware assistance for administrators and staff.</p></div>{page!=="AI Chatbot"&&<button onClick={()=>onPage(page==="Browse Articles"?"Add Article":"Add KB Category")}>＋ {page==="Browse Articles"?"Add Your Article":"Add Category"}</button>}</section><nav className={styles.kbTabs}>{[["Manage Categories","Categories"],["Browse Articles","Browse Articles"],["AI Chatbot","AI Chatbot"]].map(([key,label])=><button className={page===key?styles.kbTabActive:""} onClick={()=>onPage(key)} key={key}>{label}</button>)}</nav>{content}{toast&&<div className={styles.kbToast}>{toast}</div>}</>;
}

function KbCategories({categories,articles,onPage,onToggle}:{categories:KbCategory[];articles:KbArticle[];onPage:(p:string)=>void;onToggle:(id:string)=>void}){const school=categories.filter(x=>x.source==="School"),global=categories.filter(x=>x.source==="Global");return <><section className={styles.kbCategoryStats}>{[["CT",categories.length,"Total Categories"],["AR",articles.length,"Published Articles"],["PU",categories.filter(x=>x.visibility==="Public").length,"Public Categories"],["AD",categories.filter(x=>x.visibility==="Admin Only").length,"Admin Only"]].map(([icon,value,label])=><article key={String(label)}><i>{icon}</i><span><b>{value}</b>{label}</span></article>)}</section><article className={styles.panel}><PanelHead title="School Categories" subtitle="Custom categories written for this school" action="Add Category" onClick={()=>onPage("Add KB Category")}/>{school.length?<KbCategoryTable rows={school} articles={articles} onToggle={onToggle}/>:<Empty icon="KB" title="No categories yet" text="Create your own categories to organise articles written for this school." action="Add Category" onClick={()=>onPage("Add KB Category")}/>}</article><article className={`${styles.panel} ${styles.kbGlobalPanel}`}><PanelHead title="Global Knowledge Categories" subtitle="Maintained platform guidance available to your school"/><KbCategoryTable rows={global} articles={articles} onToggle={onToggle}/></article></>;}
function KbCategoryTable({rows,articles,onToggle}:{rows:KbCategory[];articles:KbArticle[];onToggle:(id:string)=>void}){return <div className={styles.kbCategoryTable}><div>{["Order","Name","Visibility","Articles","Status","Actions"].map(x=><b key={x}>{x}</b>)}</div>{rows.map(x=><div key={x.id}><span>{x.order}</span><p><i>KB</i><span><b>{x.name}</b><small>{x.description}</small></span></p><em>{x.visibility}</em><strong>{articles.filter(a=>a.category===x.name).length}</strong><button className={x.active?styles.kbActive:styles.kbInactive} onClick={()=>onToggle(x.id)}>{x.active?"Active":"Inactive"}</button><span><button>Edit</button><button>⋮</button></span></div>)}</div>;}

function KbCategoryForm({categories,onBack,onSave}:{categories:KbCategory[];onBack:()=>void;onSave:(category:KbCategory)=>void}){return <section className={styles.kbFormPage}><header><button onClick={onBack}>← Back to Categories</button><h1>Add Category</h1><p>Organise school-specific help articles with access and display controls.</p></header><form className={`${styles.panel} ${styles.kbForm}`} onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);onSave({id:crypto.randomUUID(),name:String(f.get("name")),parent:String(f.get("parent")),icon:String(f.get("icon")),description:String(f.get("description")),visibility:String(f.get("visibility")) as KbCategory["visibility"],order:Number(f.get("order")),active:f.get("active")==="on",source:"School"});}}><label>Category Name *<input name="name" required/></label><label>Parent Category<select name="parent"><option value="">— None (Root) —</option>{categories.filter(x=>x.source==="School").map(x=><option key={x.id}>{x.name}</option>)}</select></label><label>Icon Class<input name="icon" placeholder="fas fa-book" defaultValue="fas fa-book"/></label><label>Visibility *<select name="visibility"><option>Public</option><option>Staff Only</option><option>Admin Only</option></select></label><label>Sort Order<input name="order" type="number" min="0" defaultValue={categories.length+1}/></label><label className={styles.kbCheck}><input name="active" type="checkbox" defaultChecked/> Status: Active</label><label className={styles.kbWide}>Description<textarea name="description" placeholder="What information belongs in this category?"/></label><FormActions cancel={onBack} submit="Create"/></form></section>;}

function KbArticles({articles,categories,onPage,onOpen}:{articles:KbArticle[];categories:KbCategory[];onPage:(p:string)=>void;onOpen:(id:string)=>void}){const [search,setSearch]=useState(""),[category,setCategory]=useState("All"),[status,setStatus]=useState("All");const shown=articles.filter(x=>(category==="All"||x.category===category)&&(status==="All"||x.status===status)&&`${x.title} ${x.excerpt} ${x.tags.join(" ")}`.toLowerCase().includes(search.toLowerCase()));return <><section className={styles.kbSearchHero}><h2>How can we help?</h2><label>⌕<input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search articles, guides, FAQs…"/></label><p>{articles.length} trusted articles across {new Set(articles.map(x=>x.category)).size} categories</p></section><section className={styles.kbBrowseLayout}><aside className={styles.panel}><h3>Categories</h3><button className={category==="All"?styles.kbFilterActive:""} onClick={()=>setCategory("All")}>All <b>{articles.length}</b></button>{categories.filter(c=>articles.some(a=>a.category===c.name)).map(c=><button className={category===c.name?styles.kbFilterActive:""} onClick={()=>setCategory(c.name)} key={c.id}>{c.name}<b>{articles.filter(a=>a.category===c.name).length}</b></button>)}</aside><article className={styles.panel}><div className={styles.kbArticleToolbar}><select value={status} onChange={e=>setStatus(e.target.value)}><option>All</option><option>Published</option><option>Draft</option></select><span/><button onClick={()=>onPage("Add Article")}>＋ Add Your Article</button></div><CommExport/><div className={styles.kbArticleTable}><div>{["Article Title","Category","Status","Source","Actions"].map(x=><b key={x}>{x}</b>)}</div>{shown.map(x=><div key={x.id}><p><i>{x.pinned?"★":"KB"}</i><span><b>{x.title}</b><small>{x.excerpt} · {x.views} views</small></span></p><span>{x.category}</span><em>{x.status}</em><span>{x.source}</span><span><button onClick={()=>onOpen(x.id)}>View</button><button>Edit</button></span></div>)}</div><TablePager count={shown.length}/></article></section></>;}

function KbArticleForm({categories,onBack,onSave}:{categories:KbCategory[];onBack:()=>void;onSave:(article:KbArticle)=>void}){const [status,setStatus]=useState<KbArticle["status"]>("Draft");return <section className={styles.kbFormPage}><header><button onClick={onBack}>← Back to Articles</button><h1>Create Article</h1><p>Write clear, searchable instructions for your school team.</p></header><form className={styles.kbArticleForm} onSubmit={e=>{e.preventDefault();const f=new FormData(e.currentTarget);onSave({id:crypto.randomUUID(),title:String(f.get("title")),content:String(f.get("content")),excerpt:String(f.get("excerpt")),category:String(f.get("category")),status,visibility:String(f.get("visibility")) as KbArticle["visibility"],tags:String(f.get("tags")).split(",").map(x=>x.trim()).filter(Boolean),pinned:f.get("pinned")==="on",source:"School",updated:today(),views:0});}}><section className={styles.panel}><label>Article Title *<input name="title" required placeholder="Enter article title"/></label><label>Content *</label><div className={styles.kbEditorToolbar}>{["H1","H2","B","I","U","• List","1. List","Link","Image","Video","Undo"].map(x=><button type="button" key={x}>{x}</button>)}</div><textarea name="content" required placeholder="Write the complete step-by-step answer here…"/><label>Excerpt<textarea name="excerpt" placeholder="Short summary displayed in search results."/></label><label>Attachments<input name="attachments" type="file" multiple/></label></section><aside className={styles.panel}><PanelHead title="Publish" subtitle="Visibility and discovery"/><label>Status<select value={status} onChange={e=>setStatus(e.target.value as KbArticle["status"])}><option>Draft</option><option>Published</option></select></label><label>Visibility<select name="visibility"><option>Staff &amp; Admin</option><option>Admin Only</option><option>Public</option></select></label><label>Category<select name="category"><option value="">— Uncategorized —</option>{categories.map(x=><option key={x.id}>{x.name}{x.source==="Global"?" (Global)":""}</option>)}</select></label><label>Tags (comma separated)<input name="tags" placeholder="fees, admission"/></label><label className={styles.kbCheck}><input name="pinned" type="checkbox"/> Pin to top</label><button>{status==="Published"?"Publish":"Save Draft"}</button></aside></form></section>;}

function KbArticleDetails({article,onBack}:{article:KbArticle;onBack:()=>void}){return <section className={styles.kbArticleDetail}><button onClick={onBack}>← Back to Help Center</button><article className={styles.panel}><header><span>{article.category}</span>{article.pinned&&<em>★ PINNED</em>}<h1>{article.title}</h1><p>{article.excerpt}</p><small>Updated {article.updated} · {article.views} views · {article.visibility}</small></header><div><p>{article.content}</p><h2>Quick checklist</h2><ul><li>Confirm the correct academic session is selected.</li><li>Use an account with permission for the related module.</li><li>Review the record before saving or publishing.</li><li>Check the audit trail if a previous value needs verification.</li></ul><aside>Still need help? Ask the AI Assistant using the module name and the result you expect.</aside></div><footer>{article.tags.map(x=><span key={x}>#{x}</span>)}</footer></article></section>;}

function KbChatbot({articles}:{articles:KbArticle[]}){const [messages,setMessages]=useState<ChatMessage[]>([]),[input,setInput]=useState(""),[history,setHistory]=useState([["Fee collection this month","1 hour ago"],["Today attendance summary","1 hour ago"],["Upcoming holidays","1 day ago"],["Total student enrollment","2 days ago"]]);const suggestions=["📊 Today’s attendance summary","💰 Fee collection this month","👨‍🎓 Total student enrollment","🏫 School admission process"];function answer(question:string){const q=question.toLowerCase();if(q.includes("attendance"))return "Today’s attendance is 92%: 368 present, 24 absent and 8 late across marked classes. Grade 8 A still needs final submission.";if(q.includes("fee")||q.includes("collection"))return "This month ₹8,42,500 has been collected against ₹10,20,000 billed. ₹1,77,500 remains outstanding; 14 invoices are overdue.";if(q.includes("student")||q.includes("enrollment"))return "Current active enrollment is 400 students across Grades 6–10. Grade 8 has the highest strength with 92 students.";if(q.includes("admission"))return "Open Student Information → Student Admission, enter identity, guardian, academic and health details, verify the admission number, then save. You can also use Bulk Student Upload.";if(q.includes("holiday"))return "The next scheduled holiday is Independence Day on 15 August 2026. The calendar also shows Raksha Bandhan on 28 August.";const article=articles.find(x=>q.split(/\\s+/).some(word=>word.length>4&&`${x.title} ${x.tags.join(" ")}`.toLowerCase().includes(word)));return article?`${article.excerpt} ${article.content}`:"I can help with attendance, fees, student enrollment, admissions, examinations, library, transport and system setup. Try naming the module and what you want to check.";}function send(text=input){const value=text.trim();if(!value)return;const now=new Date().toLocaleTimeString([], {hour:"2-digit",minute:"2-digit"});setMessages(v=>[...v,{id:crypto.randomUUID(),role:"user",text:value,time:now},{id:crypto.randomUUID(),role:"assistant",text:answer(value),time:now}]);setHistory(v=>[[value,"Just now"],...v.filter(x=>x[0]!==value)]);setInput("");}return <section className={styles.kbChatLayout}><aside><button onClick={()=>setMessages([])}>＋ New Chat</button><h3>Recent conversations</h3>{history.map(([title,time])=><div key={`${title}-${time}`}><span>{title}</span><small>{time}</small></div>)}<footer><b>Intent Mode</b><span>School data + knowledge base</span></footer></aside><article><header><i>AI</i><div><b>AI Assistant</b><span>● Online</span></div><button>☼</button></header><div className={styles.kbMessages}>{messages.length?messages.map(x=><div className={x.role==="user"?styles.kbUserMessage:styles.kbAiMessage} key={x.id}><i>{x.role==="user"?"AY":"AI"}</i><p>{x.text}<small>{x.time}</small></p></div>):<section className={styles.kbChatWelcome}><i>AI</i><h2>How can I help you today?</h2><p>I can check attendance, fees and student enrollment, or find the right operating guide.</p><div>{suggestions.map(x=><button onClick={()=>send(x)} key={x}>{x}</button>)}</div></section>}</div><footer><textarea value={input} onChange={e=>setInput(e.target.value)} onKeyDown={e=>{if(e.key==="Enter"&&!e.shiftKey){e.preventDefault();send();}}} placeholder="Ask about school data..."/><button onClick={()=>send()}>➤</button><small>AI answers may use demo data. Verify important records in the source module.</small></footer></article></section>;}

