type DashboardUpdate={icon:string;text:string;date:string;group:string;page:string};
function dashboardUpdates(module:string,foundation:Foundation,students:Student[],operations:Operations,workspace:Workspace):DashboardUpdate[]{
  const formatDate=(value:string)=>{const date=new Date(value);return Number.isNaN(date.getTime())?"":date.toLocaleDateString("en-IN",{day:"2-digit",month:"short"});};
  const records=workspace.records.filter(record=>module==="Dashboard"||record.moduleKey===module).sort((a,b)=>new Date(b.updatedAt).getTime()-new Date(a.updatedAt).getTime()).slice(0,6).map(record=>({icon:record.workflow.includes("Notice")?"⚑":record.workflow.includes("Event")||record.workflow.includes("Meeting")?"▦":"●",text:record.title,date:formatDate(record.dueDate||record.updatedAt||record.recordDate),group:record.moduleKey,page:record.workflow}));
  const contextual:DashboardUpdate[]=[];
  if(module==="Dashboard"||module==="Finance & Fees"||module==="Accounts"){
    contextual.push(...operations.payments.slice(0,4).map(payment=>({icon:"₹",text:`${payment.studentName} paid ${money(payment.amountPaise)}`,date:formatDate(payment.paidOn),group:"Finance & Fees",page:"All Transactions"})));
    const due=operations.invoices.filter(invoice=>invoice.status!=="paid");if(due.length)contextual.push({icon:"!",text:`${due.length} fee ${due.length===1?"account":"accounts"} pending · ${money(operations.metrics.outstandingPaise)}`,date:"Due",group:"Finance & Fees",page:"Search Due Fees"});
  }
  if(module==="Dashboard"||module==="Student Information")contextual.push(...students.slice(0,3).map(student=>({icon:"♟",text:`${student.fullName} admitted to ${student.className}`,date:formatDate(student.admissionDate),group:"Student Information",page:"Student List"})));
  if(module==="Dashboard"||module==="Academics")contextual.push({icon:"▦",text:`${foundation.classes.length} classes and ${foundation.subjects.length} subjects configured`,date:foundation.sessions.find(session=>session.status==="active")?.name??"Current",group:"Academics",page:"Academic Dashboard"});
  if(!records.length&&!contextual.length)contextual.push({icon:"●",text:`${workspace.metrics.open} open · ${workspace.metrics.inProgress} in progress · ${workspace.metrics.completed} completed`,date:"Live",group:module,page:navigation.find(group=>group.label===module)?.items[0]??"Dashboard"});
  const session=foundation.sessions.find(item=>item.status==="active");if(module==="Dashboard"&&session)contextual.push({icon:"▣",text:`Academic session ${session.name} is active`,date:`${formatDate(session.startsOn)}–${formatDate(session.endsOn)}`,group:"Academics",page:"Academic Sessions"});
  return [...records,...contextual].filter((item,index,all)=>all.findIndex(candidate=>candidate.text===item.text)===index).slice(0,8);
}

function DashboardUpdateStrip({module,foundation,students,operations,workspace,onNavigate,canNavigate}:{module:string;foundation:Foundation;students:Student[];operations:Operations;workspace:Workspace;onNavigate:(group:string,page:string)=>void;canNavigate?:(group:string,page:string)=>boolean}){
  const updates=dashboardUpdates(module,foundation,students,operations,workspace).filter(update=>!canNavigate||canNavigate(update.group,update.page));
  return <div className={`${styles.referenceTicker} ${module==="Dashboard"?"":styles.moduleUpdateTicker}`}><b>⚑ UPDATES</b><div className={styles.updateTickerTrack}>{updates.map((update,index)=><button key={`${update.text}-${index}`} onClick={()=>onNavigate(update.group,update.page)}><i>{update.icon}</i><span>{update.text}</span><time>{update.date}</time></button>)}</div></div>;
}

function ReferenceExecutiveDashboard({schoolName,students,foundation,operations,workspace,allowedItems,onNavigate}:{schoolName:string;students:Student[];foundation:Foundation;operations:Operations;workspace:Workspace;allowedItems:Array<{group:string;item:string;icon:string}>;onNavigate:(group:string,item:string)=>void}){
  const [filter,setFilter]=useState("All"),[search,setSearch]=useState(""),[activityFilter,setActivityFilter]=useState<"All"|"Fees">("All");
  const allowedRoutes=new Set(allowedItems.map(item=>`${item.group}::${item.item}`));
  const routeAllowed=(group:string,item:string)=>group==="Dashboard"||allowedRoutes.has(`${group}::${item}`);
  const attendance=operations.metrics.attendanceMarked?Math.round(operations.metrics.present/operations.metrics.attendanceMarked*100):0;
  const staff=workspace.breakdown.find(item=>item.moduleKey==="Human Resource")?.total??0;
  const date=new Intl.DateTimeFormat("en-GB",{weekday:"long",day:"numeric",month:"long",year:"numeric"}).format(new Date());
  const schoolHour=Number(new Intl.DateTimeFormat("en-GB",{hour:"2-digit",hour12:false,timeZone:"Asia/Kolkata"}).format(new Date()));
  const greeting=schoolHour<12?"Good Morning":schoolHour<17?"Good Afternoon":"Good Evening";
  const apps=dashboardApps.filter(app=>routeAllowed(app.group,app.item)&&(filter==="All"||app.category===filter)&&`${app.item} ${app.group}`.toLowerCase().includes(search.toLowerCase()));
  const activities=[
    ...operations.payments.slice(0,6).map(payment=>({type:"Fees",title:`${payment.studentName} paid ${money(payment.amountPaise)} fee`,date:payment.paidOn,status:"Paid",tone:"green"})),
    ...students.slice(0,6).map(student=>({type:"Admission",title:`${student.fullName} student record active`,date:student.admissionDate,status:"Active",tone:"blue"})),
  ].slice(0,8);
  const visibleActivities=activityFilter==="Fees"?activities.filter(activity=>activity.type==="Fees"):activities;
  const kpis=[
    {icon:"♟",value:String(students.length),label:"Total Students",tone:"blue",points:"0,42 55,28 105,16 160,20 215,10 270,16 330,7",group:"Student Information",item:"Student List"},
    {icon:"₹",value:money(operations.metrics.collectedPaise),label:"Collected This Month",tone:"green",points:"0,43 55,34 105,20 160,25 215,13 270,17 330,8",group:"Finance & Fees",item:"Fees Dashboard"},
    {icon:"✓",value:`${attendance}%`,label:"Attendance Today",tone:"purple",points:"0,44 55,29 105,20 160,24 215,15 270,18 330,12",group:"Student Information",item:"Student Attendance"},
    {icon:"▣",value:String(staff),label:"Active Staff",tone:"violet",points:"0,36 55,30 105,32 160,25 215,29 270,18 330,22",group:"Human Resource",item:"Staff Directory"},
    {icon:"!",value:money(operations.metrics.outstandingPaise),label:"Pending Dues (All Years)",tone:"red",points:"0,12 55,18 105,23 160,38 215,31 270,45 330,49",group:"Finance & Fees",item:"Search Due Fees"},
  ].filter(kpi=>routeAllowed(kpi.group,kpi.item));
  return <section className={styles.referenceDashboard}>
    <header className={styles.referenceGreeting}><h1>{greeting}, school 👋</h1><p>Here&apos;s what&apos;s happening at {schoolName} today — {date}</p></header>
    <DashboardUpdateStrip module="Dashboard" foundation={foundation} students={students} operations={operations} workspace={workspace} onNavigate={onNavigate} canNavigate={routeAllowed}/>
    <section className={styles.referenceKpis}>{kpis.map(kpi=><button key={kpi.label} className={`${styles.referenceKpi} ${styles[`referenceKpi_${kpi.tone}`]}`} onClick={()=>onNavigate(kpi.group,kpi.item)}><div><i>{kpi.icon}</i><strong>{kpi.value}</strong><span>{kpi.label}</span></div><svg viewBox="0 0 330 60" preserveAspectRatio="none"><defs><linearGradient id={`fade-${kpi.tone}`} x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="currentColor" stopOpacity=".45"/><stop offset="100%" stopColor="currentColor" stopOpacity="0"/></linearGradient></defs><polygon points={`${kpi.points} 330,60 0,60`} fill={`url(#fade-${kpi.tone})`}/><polyline points={kpi.points} fill="none" stroke="currentColor" strokeWidth="2"/></svg></button>)}</section>
    <section className={styles.ecosystemHub}><header><div><h2>▦ All Ecosystem Modules</h2><p><b>{allowedItems.length}</b> accessible workspaces — everything your role can use, in one place</p></div><label>⌕<input value={search} onChange={event=>setSearch(event.target.value)} placeholder="Search modules..."/><kbd>/</kbd></label><nav>{["All","Finance","Academics","Students","Operations","Engagement","Admin"].map(category=><button className={filter===category?styles.ecosystemFilterActive:""} onClick={()=>setFilter(category)} key={category}>{category}</button>)}</nav></header><div className={styles.ecosystemGrid}>{apps.map(app=><button key={`${app.group}-${app.item}`} onClick={()=>onNavigate(app.group,app.item)}><i className={styles[`ecosystem_${app.tone}`]}>{app.icon}</i><span>{app.item}</span></button>)}<button className={styles.ecosystemMore} onClick={()=>onNavigate("Apps Center","Apps Center")}><i>＋</i><span>More</span></button></div></section>
    <section className={styles.referenceLowerGrid}><article className={styles.referenceActivity}><header><div><h2>Live Activity</h2><p>Real-time updates</p></div><nav><button className={activityFilter==="All"?styles.tabActive:""} onClick={()=>setActivityFilter("All")}>All</button><button className={activityFilter==="Fees"?styles.tabActive:""} onClick={()=>setActivityFilter("Fees")}>Fees</button></nav></header>{visibleActivities.length?visibleActivities.map((activity,index)=><div key={`${activity.title}-${index}`}><i className={styles[`activity${index%4}`]}>✓</i><p><b>{activity.title}</b><span>{activity.type} · {activity.status}</span></p><time>{new Date(activity.date).toLocaleDateString("en-IN",{day:"2-digit",month:"short"})}</time></div>):<Empty icon="✓" title="No recent activity" text="Admissions and payments matching this filter will appear here automatically."/>}</article><article className={styles.referenceSummary}><header><h2>Today&apos;s Overview</h2>{routeAllowed("Reports & Analytics","Reports & Analytics")&&<button onClick={()=>onNavigate("Reports & Analytics","Reports & Analytics")}>Reports ↗</button>}</header><div>{[["Open workflows",workspace.metrics.open],["In progress",workspace.metrics.inProgress],["Completed",workspace.metrics.completed],["Urgent items",workspace.metrics.urgent]].map(([label,value])=><p key={label}><span>{label}</span><b>{value}</b></p>)}</div></article></section>
  </section>;
}
